<#
PowerFlow V7.2 - Session Overlay + Dashboard dual display deployer
All-in-one self-contained deployment script.

Mission:
- Write/update SessionOverlay V2 files.
- Inject session_context into pf_behavioral_alert_mapper.py without filtering alerts.
- Install dashboard dual display hardening and freshness module.
- Validate Python modules, session tests, runner, JSON contract.
- Optionally git add/commit/push.

Usage from repository root:
  powershell -ExecutionPolicy Bypass -File .\deploy_powerflow_v72_session_dashboard_all_in_one.ps1

Usage from anywhere:
  powershell -ExecutionPolicy Bypass -File .\deploy_powerflow_v72_session_dashboard_all_in_one.ps1 -CorePath "C:\Users\User\Desktop\ProjetPowerFlow\IA\GPT\Core"

Safe modes:
  -DryRun    : report intended file writes, no file changes, no git
  -NoGit     : deploy and validate without git add/commit/push
  -NoPush    : commit locally but do not push
#>

[CmdletBinding()]
param(
  [string]$CorePath = ".",
  [string]$CommitMessage = "SessionOverlay: V2 complete injection + Dashboard dual display hardening",
  [string]$DashboardTarget = "",
  [switch]$NoGit,
  [switch]$NoPush,
  [switch]$DryRun
)

$ErrorActionPreference = "Stop"
$script:Results = New-Object System.Collections.Generic.List[object]
$script:HadFailure = $false
$script:CommitCreated = $false

function Add-DeployResult {
  param(
    [string]$Step,
    [string]$Status,
    [string]$Detail = ""
  )
  $script:Results.Add([pscustomobject]@{ Step = $Step; Status = $Status; Detail = $Detail }) | Out-Null
  if ($Status -eq "FAIL") { $script:HadFailure = $true }
}

function Invoke-DeployStep {
  param(
    [string]$Step,
    [scriptblock]$Body,
    [switch]$Critical
  )
  try {
    $detail = & $Body
    if ($null -eq $detail) { $detail = "" }
    Add-DeployResult -Step $Step -Status "PASS" -Detail ([string]$detail)
  } catch {
    Add-DeployResult -Step $Step -Status "FAIL" -Detail $_.Exception.Message
    if ($Critical) { throw }
  }
}

function Write-Utf8FileFromB64 {
  param(
    [string]$RelativePath,
    [string]$B64,
    [string]$RootPath,
    [string]$BackupRoot
  )
  $target = Join-Path $RootPath $RelativePath
  $parent = Split-Path -Parent $target
  if (-not (Test-Path $parent)) { New-Item -ItemType Directory -Path $parent -Force | Out-Null }

  $bytes = [System.Convert]::FromBase64String($B64)
  $content = [System.Text.Encoding]::UTF8.GetString($bytes)

  if ($DryRun) { return "DRYRUN would write $RelativePath" }

  if (Test-Path $target) {
    $existing = Get-Content $target -Raw -Encoding UTF8
    if ($existing -eq $content) { return "UNCHANGED $RelativePath" }
    $backupPath = Join-Path $BackupRoot $RelativePath
    $backupParent = Split-Path -Parent $backupPath
    if (-not (Test-Path $backupParent)) { New-Item -ItemType Directory -Path $backupParent -Force | Out-Null }
    Copy-Item $target $backupPath -Force
  }

  [System.IO.File]::WriteAllText($target, $content, [System.Text.UTF8Encoding]::new($false))
  return "WROTE $RelativePath"
}

function Invoke-External {
  param([string]$FilePath, [string[]]$Arguments)
  & $FilePath @Arguments
  $code = $LASTEXITCODE
  if ($code -ne 0) { throw "$FilePath $($Arguments -join ' ') exited with code $code" }
}

function Resolve-DashboardTarget {
  param([string]$RootPath, [string]$ExplicitTarget)
  if ($ExplicitTarget -and $ExplicitTarget.Trim().Length -gt 0) { return $ExplicitTarget }
  $candidates = @(
    "dashboard_live.html",
    "dashboard_live_v7.2_final.html",
    "dashboard_live_v7.2.html",
    "dashboard_live_v7.2_max.html"
  )
  foreach ($candidate in $candidates) {
    if (Test-Path (Join-Path $RootPath $candidate)) { return $candidate }
  }
  return "dashboard_live.html"
}

$Payload = @(
  @{ Path = "pf_session_overlay.py"; B64 = "" }
  @{ Path = "run_session_overlay_once.py"; B64 = "" }
  @{ Path = "patch_behavioral_alert_mapper.py"; B64 = "" }
  @{ Path = "test_session_overlay.py"; B64 = "" }
  @{ Path = "dashboard_freshness_module.js"; B64 = "" }
  @{ Path = "dashboard_session_card.html"; B64 = "" }
  @{ Path = "dashboard_dual_display_patch.html"; B64 = "" }
  @{ Path = "dashboard_contract_v2.json"; B64 = "" }
  @{ Path = "INTEGRATION_GUIDE.md"; B64 = "" }
  @{ Path = "LEXIQUE_PATCH_SESSION_OVERLAY.md"; B64 = "" }
  @{ Path = "REGISTRE_BRIQUES_PATCH_SESSION.md"; B64 = "" }
  @{ Path = "validation_checklist.md"; B64 = "" }
  @{ Path = "git_deploy_session_dashboard.ps1"; B64 = "" }
)

$CorePathResolved = (Resolve-Path $CorePath).Path
$Stamp = (Get-Date).ToUniversalTime().ToString("yyyyMMddTHHmmssZ")
$BackupRoot = Join-Path $CorePathResolved ("backups\session_dashboard_" + $Stamp)

Write-Host "PowerFlow V7.2 Session/Dashboard deploy" -ForegroundColor Cyan
Write-Host "CorePath: $CorePathResolved"
Write-Host "DryRun: $DryRun  NoGit: $NoGit  NoPush: $NoPush"
Write-Host ""

Push-Location $CorePathResolved
try {
  Invoke-DeployStep "create backup directory" {
    if ($DryRun) { return "DRYRUN backup root $BackupRoot" }
    New-Item -ItemType Directory -Path $BackupRoot -Force | Out-Null
    return $BackupRoot
  } -Critical

  Invoke-DeployStep "write embedded deployment files" {
    $messages = New-Object System.Collections.Generic.List[string]
    foreach ($item in $Payload) {
      $msg = Write-Utf8FileFromB64 -RelativePath $item.Path -B64 $item.B64 -RootPath $CorePathResolved -BackupRoot $BackupRoot
      $messages.Add($msg) | Out-Null
    }
    return ($messages -join "; ")
  } -Critical



  Invoke-DeployStep "install all-in-one deploy script in repo root" {
    if ($DryRun) { return "DRYRUN would copy all-in-one script to repo root" }
    if (-not $PSCommandPath) { return "SKIP PSCommandPath unavailable" }
    $selfTarget = Join-Path $CorePathResolved "deploy_powerflow_v72_session_dashboard_all_in_one.ps1"
    $selfSource = (Resolve-Path $PSCommandPath).Path
    if ($selfSource -eq $selfTarget) { return "UNCHANGED deploy script already in repo root" }
    if (Test-Path $selfTarget) {
      Copy-Item $selfTarget (Join-Path $BackupRoot "deploy_powerflow_v72_session_dashboard_all_in_one.ps1") -Force
    }
    Copy-Item $selfSource $selfTarget -Force
    return "WROTE deploy_powerflow_v72_session_dashboard_all_in_one.ps1"
  } -Critical

  Invoke-DeployStep "py_compile core deploy files" {
    if ($DryRun) { return "DRYRUN skip py_compile" }
    Invoke-External python @("-m", "py_compile", ".\pf_session_overlay.py", ".\patch_behavioral_alert_mapper.py", ".\run_session_overlay_once.py", ".\test_session_overlay.py")
    return "py_compile PASS"
  } -Critical

  Invoke-DeployStep "test_session_overlay.py" {
    if ($DryRun) { return "DRYRUN skip tests" }
    Invoke-External python @(".\test_session_overlay.py")
    return "session overlay unit tests PASS"
  } -Critical

  Invoke-DeployStep "run_session_overlay_once.py --pretty" {
    if ($DryRun) { return "DRYRUN skip runner" }
    Invoke-External python @(".\run_session_overlay_once.py", "--pretty")
    return "runner PASS"
  } -Critical

  Invoke-DeployStep "patch pf_behavioral_alert_mapper.py" {
    if ($DryRun) { return "DRYRUN skip mapper patch" }
    if (-not (Test-Path ".\pf_behavioral_alert_mapper.py")) { return "SKIP target mapper missing" }
    Invoke-External python @(".\patch_behavioral_alert_mapper.py", "--file", ".\pf_behavioral_alert_mapper.py")
    return "mapper patched or already patched"
  } -Critical

  Invoke-DeployStep "py_compile pf_behavioral_alert_mapper.py" {
    if ($DryRun) { return "DRYRUN skip mapper compile" }
    if (-not (Test-Path ".\pf_behavioral_alert_mapper.py")) { return "SKIP target mapper missing" }
    Invoke-External python @("-m", "py_compile", ".\pf_behavioral_alert_mapper.py")
    return "mapper compile PASS"
  } -Critical

  Invoke-DeployStep "validate dashboard contract V2" {
    if ($DryRun) { return "DRYRUN skip contract validation" }
    Get-Content ".\dashboard_contract_v2.json" -Raw -Encoding UTF8 | ConvertFrom-Json | Out-Null
    return "dashboard_contract_v2.json valid JSON"
  } -Critical

  Invoke-DeployStep "apply dashboard dual display patch" {
    $targetRel = Resolve-DashboardTarget -RootPath $CorePathResolved -ExplicitTarget $DashboardTarget
    $targetAbs = Join-Path $CorePathResolved $targetRel
    $patchAbs = Join-Path $CorePathResolved "dashboard_dual_display_patch.html"
    if ($DryRun) { return "DRYRUN would copy dashboard_dual_display_patch.html to $targetRel" }
    if (-not (Test-Path $patchAbs)) { throw "dashboard_dual_display_patch.html missing" }
    if (Test-Path $targetAbs) {
      $backupTarget = Join-Path $BackupRoot $targetRel
      $backupParent = Split-Path -Parent $backupTarget
      if (-not (Test-Path $backupParent)) { New-Item -ItemType Directory -Path $backupParent -Force | Out-Null }
      Copy-Item $targetAbs $backupTarget -Force
    }
    Copy-Item $patchAbs $targetAbs -Force
    return "dashboard patched: $targetRel"
  } -Critical

  Invoke-DeployStep "git add/commit/push" {
    if ($DryRun) { return "DRYRUN skip git" }
    if ($NoGit) { return "SKIP NoGit" }
    if (-not (Test-Path ".\.git")) { return "SKIP no .git directory" }

    $targetRel = Resolve-DashboardTarget -RootPath $CorePathResolved -ExplicitTarget $DashboardTarget
    $gitFiles = @(
      "pf_session_overlay.py",
      "run_session_overlay_once.py",
      "patch_behavioral_alert_mapper.py",
      "test_session_overlay.py",
      "pf_behavioral_alert_mapper.py",
      "dashboard_dual_display_patch.html",
      "dashboard_freshness_module.js",
      "dashboard_session_card.html",
      "dashboard_contract_v2.json",
      $targetRel,
      "INTEGRATION_GUIDE.md",
      "LEXIQUE_PATCH_SESSION_OVERLAY.md",
      "REGISTRE_BRIQUES_PATCH_SESSION.md",
      "validation_checklist.md",
      "git_deploy_session_dashboard.ps1",
      "deploy_powerflow_v72_session_dashboard_all_in_one.ps1"
    ) | Select-Object -Unique

    foreach ($f in $gitFiles) { if (Test-Path $f) { git add -- $f | Out-Null } }
    $dirty = git status --porcelain
    if (-not $dirty) { return "SKIP no changes to commit" }

    git commit -m $CommitMessage | Out-Host
    if ($LASTEXITCODE -ne 0) { throw "git commit failed" }
    $script:CommitCreated = $true

    if ($NoPush) { return "COMMIT created, push skipped" }
    git push | Out-Host
    if ($LASTEXITCODE -ne 0) { throw "git push failed" }
    return "COMMIT + PUSH PASS"
  } -Critical
}
finally {
  Pop-Location
  Write-Host ""
  Write-Host "=== PowerFlow deploy report ===" -ForegroundColor Cyan
  $script:Results | Format-Table -AutoSize
}

if ($script:HadFailure) { exit 1 }
exit 0
